 .source-document {
 --page-bg: #eef1f4;
 --card-bg: #ffffff;
 --field-bg: #f5f6f7;
 --field-border: #dcdfe3;
 --field-border-focus: #111111;
 --text-primary: #1f2328;
 --text-secondary: #5b6470;
 --accent: #e0523f;
 --button-bg: #111111;
 --button-bg-hover: #2b2b2b;
 --button-text: #ffffff;
 --radius: 10px;
 --shadow: 0 10px 30px rgba(17, 17, 17, 0.08);
}
.page-content .calculatorWrap {
 box-sizing: border-box;
}
.page-content .calculatorWrap {
 background: var(--page-bg);
}
.page-content .calculatorWrap {
 background: var(--card-bg);
 color: var(--text-primary);
/*   font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; */
 max-width: 620px;
 margin: 48px auto;
 padding: 44px 48px 48px;
 border-radius: 16px;
 box-shadow: var(--shadow);
 line-height: 1.5;
}
.page-content .calculatorWrap h1 {
 font-size: 1.6rem;
 font-weight: 700;
 color: var(--text-primary);
 margin: 0 0 32px;
 padding-bottom: 20px;
 border-bottom: 1px solid #ececec;
}
.page-content .calculatorWrap .question {
 margin-bottom: 26px;
 padding-bottom: 22px;
 border-bottom: 1px solid #f0f0f0;
}
.page-content .calculatorWrap .question:last-of-type {
 border-bottom: none;
}
.page-content .calculatorWrap .question p {
 font-weight: 600;
 font-size: 0.98rem;
 color: var(--text-primary);
 margin: 0 0 12px;
}
/* Radio question rows */
.page-content .calculatorWrap input[type="radio"] {
 width: 17px;
 height: 17px;
 margin: 0 8px 10px 0;
 accent-color: var(--text-primary);
 vertical-align: middle;
 cursor: pointer;
}
.page-content .calculatorWrap .question label {
 font-size: 0.95rem;
 color: var(--text-secondary);
 margin-right: 18px;
 cursor: pointer;
 vertical-align: middle;
}
/* Text inputs */
.page-content .calculatorWrap input:not([type="radio"]) {
 width: 100%;
 background: var(--field-bg);
 border: 1px solid var(--field-border);
 border-radius: var(--radius);
 padding: 13px 14px;
 font-size: 0.95rem;
 color: var(--text-primary);
 transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.page-content .calculatorWrap .question input::placeholder {
 color: #111;
 opacity: 8;
}
.page-content .calculatorWrap .question input:focus::placeholder {
 opacity: 9;
}
.page-content .calculatorWrap input:not([type="radio"])::placeholder {
 color: #9aa0a6;
}
.page-content .calculatorWrap input:not([type="radio"]):focus {
 outline: none;
 border-color: var(--field-border-focus);
 box-shadow: 0 0 0 3px rgba(17, 17, 17, 0.06);
 background: #ffffff;
}
/* Calculate button */
.page-content .calculatorWrap button {
 display: inline-block;
 background: var(--button-bg);
 color: var(--button-text);
 border: none;
 border-radius: var(--radius);
 padding: 14px 36px;
 font-size: 1rem;
 font-weight: 600;
 cursor: pointer;
 margin-top: 6px;
 transition: background 0.15s ease, transform 0.05s ease;
}
.page-content .calculatorWrap button:hover {
 background: var(--button-bg-hover);
}
.page-content .calculatorWrap button:active {
 transform: translateY(1px);
}
/* Result */
.page-content .calculatorWrap #award_amount {
 font-size: 1.3rem;
 font-weight: 700;
 color: var(--accent);
 margin-top: 18px;
}
.page-content .calculatorWrap #award_amount:empty {
 margin-top: 0;
}
/* Responsive */
@media (max-width: 680px) {
 .page-content .calculatorWrap  {
 margin: 0;
 border-radius: 0;
 padding: 32px 22px 40px;
 box-shadow: none;
 min-height: 100vh;
 }
} 
